import itertools

def find_sums_of_two_distinct_squares(max_y):
    sums = set()
    # Iterate through x < y
    for y in range(2, max_y + 1):
        for x in range(1, y):
            sums.add(x**2 + y**2)

    sorted_sums = sorted(list(sums))
    return sorted_sums

# We need at least 20 elements. Let's check up to y=15 to be safe.
all_sums = find_sums_of_two_distinct_squares(15)

if len(all_sums) >= 20:
    print(f"Found {len(all_sums)} distinct sums of two distinct positive squares up to y=15.")
    print("The 20th smallest sum is:", all_sums[19])
else:
    print(f"Only found {len(all_sums)} sums. Increasing limit.")

import itertools

def generate_candidates(max_y):
    candidates = set()
    for x in range(1, max_y):
        for y in range(x + 1, max_y + 1):
            m = x**2 + y**2
            candidates.add(m)
    return sorted(list(candidates))

# Checking up to max_y = 10 to ensure we capture candidates beyond the original 7
candidates_list = generate_candidates(10)
print(f"Total number of unique candidates found: {len(candidates_list)}")
print("First 25 candidates:")
for i in range(min(25, len(candidates_list))):
    print(f"{i+1}: {candidates_list[i]}")

# Explicitly checking for 68 (2^2 + 8^2)
print("Checking for 68...")
if 68 in candidates_list:
    index = candidates_list.index(68)
    print(f"68 found at index {index+1}.")
else:
    print("68 not found in the generated list (should be covered if max_y >= 8).")
